package domain

import "errors"

var (
	ErrNotFound     = errors.New("not found")
	ErrConflict     = errors.New("conflict")
	ErrInvalid      = errors.New("invalid")
	ErrUnauthorized = errors.New("unauthorized")
)

// Error preserves a stable domain error category while allowing callers to
// attach a safe, human-readable message and an underlying cause.
type Error struct {
	Kind    error
	Message string
	Cause   error
}

func (e *Error) Error() string {
	if e.Message != "" {
		return e.Message
	}
	return e.Kind.Error()
}

func (e *Error) Unwrap() error { return e.Cause }

func (e *Error) Is(target error) bool { return target == e.Kind }

func NewNotFound(message string) error     { return newError(ErrNotFound, message) }
func NewConflict(message string) error     { return newError(ErrConflict, message) }
func NewInvalid(message string) error      { return newError(ErrInvalid, message) }
func NewUnauthorized(message string) error { return newError(ErrUnauthorized, message) }

func Wrap(kind, message string, cause error) error {
	category := ErrInvalid
	switch kind {
	case "not_found":
		category = ErrNotFound
	case "conflict":
		category = ErrConflict
	case "unauthorized":
		category = ErrUnauthorized
	}
	return &Error{Kind: category, Message: message, Cause: cause}
}

func newError(kind error, message string) error { return &Error{Kind: kind, Message: message} }

// IsKind reports whether err belongs to the requested domain category.
func IsKind(err, kind error) bool { return errors.Is(err, kind) }

// Package domain contains shared IAM domain primitives.
package domain

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
)

// ID is the common representation of an entity identifier. Values are UUID
// version 4 strings, generated with crypto/rand.
type ID string

type UserID ID
type OrganizationID ID
type SessionID ID
type InviteID ID
type RoleID ID
type APIKeyID ID
type TokenFamilyID ID

// NewID returns a new random UUID version 4 identifier.
func NewID() (ID, error) {
	var value [16]byte
	if _, err := rand.Read(value[:]); err != nil {
		return "", fmt.Errorf("generate id: %w", err)
	}
	value[6] = (value[6] & 0x0f) | 0x40
	value[8] = (value[8] & 0x3f) | 0x80
	encoded := make([]byte, 36)
	hex.Encode(encoded[0:8], value[0:4])
	hex.Encode(encoded[9:13], value[4:6])
	hex.Encode(encoded[14:18], value[6:8])
	hex.Encode(encoded[19:23], value[8:10])
	hex.Encode(encoded[24:36], value[10:16])
	encoded[8], encoded[13], encoded[18], encoded[23] = '-', '-', '-', '-'
	return ID(encoded), nil
}

func newTypedID[T ~string](newValue func() (ID, error)) (T, error) {
	id, err := newValue()
	return T(id), err
}

func NewUserID() (UserID, error) { return newTypedID[UserID](NewID) }

func NewOrganizationID() (OrganizationID, error) { return newTypedID[OrganizationID](NewID) }

func NewSessionID() (SessionID, error) { return newTypedID[SessionID](NewID) }

func NewInviteID() (InviteID, error) { return newTypedID[InviteID](NewID) }

func NewRoleID() (RoleID, error) { return newTypedID[RoleID](NewID) }

func NewAPIKeyID() (APIKeyID, error) { return newTypedID[APIKeyID](NewID) }

func NewTokenFamilyID() (TokenFamilyID, error) { return newTypedID[TokenFamilyID](NewID) }

// ParseID validates the textual UUID representation before converting it to ID.
func ParseID(value string) (ID, error) {
	if len(value) != 36 || value[8] != '-' || value[13] != '-' || value[18] != '-' || value[23] != '-' {
		return "", errors.New("invalid id")
	}
	var raw [16]byte
	if _, err := hex.Decode(raw[:4], []byte(value[0:8])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[4:6], []byte(value[9:13])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[6:8], []byte(value[14:18])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[8:10], []byte(value[19:23])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[10:16], []byte(value[24:36])); err != nil {
		return "", errors.New("invalid id")
	}
	return ID(value), nil
}

package domain

import "time"

// EmailVerificationState describes the state of a user's email address.
// Keeping this state explicit avoids inferring verification from the presence
// or absence of unrelated user data.
type EmailVerificationState string

const (
	EmailVerificationPending  EmailVerificationState = "pending"
	EmailVerificationVerified EmailVerificationState = "verified"
)

// PasswordMaterial contains only the derived password material needed for
// password verification. It deliberately has no JSON representation: this
// type must not leak through API responses, logs, or other JSON envelopes.
type PasswordMaterial struct {
	Salt       []byte
	Hash       []byte
	Iterations uint32
}

// MarshalJSON prevents accidental serialization even when PasswordMaterial is
// marshaled directly rather than as part of User.
func (PasswordMaterial) MarshalJSON() ([]byte, error) { return []byte("{}"), nil }

// User is the private domain representation of an account. PasswordMaterial
// is kept separate from the fields exposed by PublicUserProfile.
type User struct {
	ID                     UserID                 `json:"id"`
	Email                  string                 `json:"email"`
	EmailVerified          bool                   `json:"email_verified"`
	EmailVerificationState EmailVerificationState `json:"email_verification_state"`
	PasswordMaterial       PasswordMaterial       `json:"-"`
	CreatedAt              time.Time              `json:"created_at"`
	UpdatedAt              time.Time              `json:"updated_at"`
}

// PublicUserProfile is the safe representation of a user for API responses.
// It contains account identity and verification state, but no password data.
type PublicUserProfile struct {
	ID                     UserID                 `json:"id"`
	Email                  string                 `json:"email"`
	EmailVerified          bool                   `json:"email_verified"`
	EmailVerificationState EmailVerificationState `json:"email_verification_state"`
	CreatedAt              time.Time              `json:"created_at"`
}

// PublicProfile returns the user data that may be sent to a client.
func (u User) PublicProfile() PublicUserProfile {
	return PublicUserProfile{
		ID:                     u.ID,
		Email:                  u.Email,
		EmailVerified:          u.EmailVerified,
		EmailVerificationState: u.EmailVerificationState,
		CreatedAt:              u.CreatedAt,
	}
}

package repository

import (
	"bytes"
	"sync"

	"benchmark.local/iam/internal/domain"
)

// SessionRepository is a concurrency-safe in-memory store. The token index
// contains SHA-256 digests only; the clear refresh token is never retained.
type SessionRepository struct {
	mu       sync.RWMutex
	sessions map[domain.SessionID]domain.Session
	byToken  map[[32]byte]domain.SessionID
}

func NewSessionRepository() *SessionRepository {
	return &SessionRepository{
		sessions: make(map[domain.SessionID]domain.Session),
		byToken:  make(map[[32]byte]domain.SessionID),
	}
}

// Create stores a session and hashes refreshToken before it enters the
// repository. A session ID, user, family, and expiry are required.
func (r *SessionRepository) Create(session domain.Session, refreshToken string) error {
	if session.ID == "" || session.UserID == "" || session.TokenFamilyID == "" ||
		session.ExpiresAt.IsZero() ||
		!domain.ValidRefreshToken(refreshToken) {
		return domain.NewInvalid("invalid session")
	}
	digest := domain.HashRefreshToken(refreshToken)
	var key [32]byte
	copy(key[:], digest)
	session.RefreshTokenHash = digest
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.sessions[session.ID]; exists {
		return domain.NewConflict("session already exists")
	}
	if _, exists := r.byToken[key]; exists {
		return domain.NewConflict("refresh token already exists")
	}
	r.sessions[session.ID] = cloneSession(session)
	r.byToken[key] = session.ID
	return nil
}

// CreateSession is a descriptive alias for Create.
func (r *SessionRepository) CreateSession(session domain.Session, refreshToken string) error {
	return r.Create(session, refreshToken)
}

// GetByID returns a detached session, including revoked sessions so callers
// can distinguish rotation replay from an unknown token.
func (r *SessionRepository) GetByID(id domain.SessionID) (domain.Session, error) {
	r.mu.RLock()
	session, ok := r.sessions[id]
	r.mu.RUnlock()
	if !ok {
		return domain.Session{}, domain.NewNotFound("session not found")
	}
	return cloneSession(session), nil
}

// GetByRefreshToken finds a session by hashing the presented opaque value.
func (r *SessionRepository) GetByRefreshToken(refreshToken string) (domain.Session, error) {
	if !domain.ValidRefreshToken(refreshToken) {
		return domain.Session{}, domain.NewNotFound("session not found")
	}
	digest := domain.HashRefreshToken(refreshToken)
	var key [32]byte
	copy(key[:], digest)
	r.mu.RLock()
	id, ok := r.byToken[key]
	session := r.sessions[id]
	r.mu.RUnlock()
	if !ok {
		return domain.Session{}, domain.NewNotFound("session not found")
	}
	return cloneSession(session), nil
}

// GetByToken is a concise alias for GetByRefreshToken.
func (r *SessionRepository) GetByToken(refreshToken string) (domain.Session, error) {
	return r.GetByRefreshToken(refreshToken)
}

func (r *SessionRepository) Revoke(id domain.SessionID) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	session, ok := r.sessions[id]
	if !ok {
		return domain.NewNotFound("session not found")
	}
	session.Revoked = true
	r.sessions[id] = session
	return nil
}

// RevokeFamily revokes every session belonging to the token family.
func (r *SessionRepository) RevokeFamily(family domain.TokenFamilyID) int {
	if family == "" {
		return 0
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	count := 0
	for id, session := range r.sessions {
		if session.TokenFamilyID == family && !session.Revoked {
			session.Revoked = true
			r.sessions[id] = session
			count++
		}
	}
	return count
}

// RevokeByUser revokes all active sessions owned by userID and returns the
// number of sessions changed. It is deliberately atomic with respect to
// session creation and refresh rotation.
func (r *SessionRepository) RevokeByUser(userID domain.UserID) int {
	if userID == "" {
		return 0
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	count := 0
	for id, session := range r.sessions {
		if session.UserID == userID && !session.Revoked {
			session.Revoked = true
			r.sessions[id] = session
			count++
		}
	}
	return count
}

// Rotate atomically replaces the presented session with a new session in the
// same token family. The old token remains indexed so replay can revoke the
// entire family.
func (r *SessionRepository) Rotate(oldToken string, replacement domain.Session, newToken string) (domain.Session, error) {
	if !domain.ValidRefreshToken(oldToken) || !domain.ValidRefreshToken(newToken) || replacement.ID == "" || replacement.UserID == "" || replacement.TokenFamilyID == "" || replacement.ExpiresAt.IsZero() {
		return domain.Session{}, domain.NewInvalid("invalid session rotation")
	}
	oldDigest := domain.HashRefreshToken(oldToken)
	var oldKey [32]byte
	copy(oldKey[:], oldDigest)
	newDigest := domain.HashRefreshToken(newToken)
	var newKey [32]byte
	copy(newKey[:], newDigest)
	r.mu.Lock()
	defer r.mu.Unlock()
	oldID, ok := r.byToken[oldKey]
	if !ok {
		return domain.Session{}, domain.NewNotFound("session not found")
	}
	old, ok := r.sessions[oldID]
	if !ok {
		return domain.Session{}, domain.NewNotFound("session not found")
	}
	// 4.3:reuse detection — a rotated token is retained in the index so that
	// presenting it again revokes every member of its family, including tokens
	// issued after the original rotation.
	if old.Revoked {
		for id, session := range r.sessions {
			if session.TokenFamilyID == old.TokenFamilyID {
				session.Revoked = true
				r.sessions[id] = session
			}
		}
		return domain.Session{}, domain.NewUnauthorized("refresh token already used")
	}
	if _, exists := r.sessions[replacement.ID]; exists {
		return domain.Session{}, domain.NewConflict("session already exists")
	}
	if _, exists := r.byToken[newKey]; exists {
		return domain.Session{}, domain.NewConflict("refresh token already exists")
	}
	if replacement.UserID != old.UserID || replacement.TokenFamilyID != old.TokenFamilyID {
		return domain.Session{}, domain.NewInvalid("invalid session rotation")
	}
	old.Revoked = true
	r.sessions[oldID] = old
	replacement.RefreshTokenHash = newDigest
	r.sessions[replacement.ID] = cloneSession(replacement)
	r.byToken[newKey] = replacement.ID
	return cloneSession(replacement), nil
}

func (r *SessionRepository) ListByUser(userID domain.UserID) []domain.Session {
	r.mu.RLock()
	result := make([]domain.Session, 0)
	for _, session := range r.sessions {
		if session.UserID == userID {
			result = append(result, cloneSession(session))
		}
	}
	r.mu.RUnlock()
	return result
}

func cloneSession(session domain.Session) domain.Session {
	session.RefreshTokenHash = bytes.Clone(session.RefreshTokenHash)
	return session
}

package repository

import (
	"bytes"
	"sync"
	"time"

	"benchmark.local/iam/internal/domain"
)

type PasswordReset struct {
	UserID    domain.UserID
	TokenHash []byte
	ExpiresAt time.Time
	Used      bool
}

type PasswordResetRepository struct {
	mu     sync.Mutex
	tokens map[[32]byte]PasswordReset
}

func NewPasswordResetRepository() *PasswordResetRepository {
	return &PasswordResetRepository{tokens: make(map[[32]byte]PasswordReset)}
}

func (r *PasswordResetRepository) Create(userID domain.UserID, token string, expiresAt time.Time) error {
	if userID == "" || !domain.ValidPasswordResetToken(token) || expiresAt.IsZero() {
		return domain.NewInvalid("invalid password reset token")
	}
	digest := domain.HashPasswordResetToken(token)
	var key [32]byte
	copy(key[:], digest)
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.tokens[key]; exists {
		return domain.NewConflict("password reset token already exists")
	}
	r.tokens[key] = PasswordReset{UserID: userID, TokenHash: bytes.Clone(digest), ExpiresAt: expiresAt}
	return nil
}

func (r *PasswordResetRepository) Consume(token string, now time.Time) (domain.UserID, error) {
	if !domain.ValidPasswordResetToken(token) {
		return "", domain.NewUnauthorized("invalid password reset token")
	}
	digest := domain.HashPasswordResetToken(token)
	var key [32]byte
	copy(key[:], digest)
	r.mu.Lock()
	defer r.mu.Unlock()
	record, ok := r.tokens[key]
	if !ok || record.Used || !now.Before(record.ExpiresAt) {
		return "", domain.NewUnauthorized("invalid password reset token")
	}
	record.Used = true
	r.tokens[key] = record
	return record.UserID, nil
}

